/* square.h */
#define SQUARE(x) ((x) * (x))
int area(int w, int h);      /* a declaration: no body */

/* area.c */
int area(int w, int h) { return w * h; }   /* the definition */

/* main.c */
#include <stdio.h>
#include "square.h"
int main(void) {
    printf("%d %d\n", SQUARE(3), area(2, 5));   /* prints 9 10 */
    return 0;
}

#include <stdio.h>

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

int main(void) {
    int x = 1, y = 2;
    swap(&x, &y);
    printf("%d %d\n", x, y);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *v = NULL;
    size_t len = 0, cap = 0;
    for (int i = 1; i <= 5; i++) {
        if (len == cap) {
            size_t ncap = cap ? cap * 2 : 2;
            int *nv = realloc(v, ncap * sizeof *nv);
            if (!nv) { free(v); return 1; }
            v = nv;
            cap = ncap;
        }
        v[len++] = i * 10;
    }
    printf("len=%zu cap=%zu last=%d\n", len, cap, v[len - 1]);
    free(v);
    return 0;
}

